command:
// Fold each seat's older fog copies on the viewed scene into its newest — GM only.
const api = game.modules.get("acks-extras")?.api?.formation ?? globalThis.acksExtras?.formation;
if (!api?.mergeFogCopies) return ui.notifications.error("ACKS Exploration Formations is not active.");
if (!game.user.isGM) return ui.notifications.warn("Merging fog copies is a GM tool.");
await api.mergeFogCopies();
